from AlgorithmImportByName import *

class QuantConnectLean(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        self.spy_closes = []
        self.aapl_closes = []

    def OnData(self, data):
        for ticker in self.tickers:
            if not data.ContainsKey(self.symbols[ticker]):
                return

        self.spy_closes.append(data[self.symbols["SPY"]].Close)
        self.aapl_closes.append(data[self.symbols["AAPL"]].Close)

        if len(self.spy_closes) < 51 or len(self.aapl_closes) < 14:
            return

        self._EvaluateSells()
        self._EvaluateBuys()

    def _EvaluateSells(self):
        if self.Portfolio[self.symbols["SPY"]].Quantity > 0:
            today_sma = sum(self.spy_closes[-50:]) / 50
            yesterday_sma = sum(self.spy_closes[-51:-1]) / 50
            today_close = self.spy_closes[-1]
            yesterday_close = self.spy_closes[-2]

            if yesterday_close > yesterday_sma and today_close <= today_sma:
                self.Liquidate(self.symbols["SPY"])

        if self.Portfolio[self.symbols["AAPL"]].Quantity > 0:
            rsi = self._CalculateRSI(self.aapl_closes[-14:])
            if rsi > 60:
                self.Liquidate(self.symbols["AAPL"])

    def _EvaluateBuys(self):
        if self.Portfolio[self.symbols["SPY"]].Quantity == 0:
            today_sma = sum(self.spy_closes[-50:]) / 50
            yesterday_sma = sum(self.spy_closes[-51:-1]) / 50
            today_close = self.spy_closes[-1]
            yesterday_close = self.spy_closes[-2]

            if yesterday_close <= yesterday_sma and today_close > today_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.4
                shares = int(target_value / today_close)
                if shares > 0:
                    self.Buy(self.symbols["SPY"], shares)

        if self.Portfolio[self.symbols["AAPL"]].Quantity == 0 and len(self.aapl_closes) >= 4:
            red_count = 0
            if self.aapl_closes[-3] < self.aapl_closes[-4]:
                red_count += 1
            if self.aapl_closes[-2] < self.aapl_closes[-3]:
                red_count += 1
            if self.aapl_closes[-1] < self.aapl_closes[-2]:
                red_count += 1

            if red_count == 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    today_close = self.aapl_closes[-1]
                    shares = int(20000 / today_close)
                    self.Buy(self.symbols["AAPL"], shares)

    def _CalculateRSI(self, prices):
        if len(prices) < 2:
            return None

        gains = 0
        losses = 0
        for i in range(1, len(prices)):
            change = prices[i] - prices[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / (len(prices) - 1)
        avg_loss = losses / (len(prices) - 1)

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 0

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

