class QuantConnectLEANAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = ['SPY', 'AAPL', 'IBM', 'BAC', 'AIG']
        for symbol in self.symbols:
            self.AddEquity(symbol, Resolution.Daily)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.closes = {symbol: [] for symbol in self.symbols}

    def OnData(self, data):
        for symbol in self.symbols:
            if not data.ContainsKey(symbol):
                return

        for symbol in self.symbols:
            self.closes[symbol].append(data[symbol].Close)

        if len(self.closes['SPY']) < 21 or len(self.closes['AAPL']) < 14:
            return

        spy_close = data['SPY'].Close
        aapl_close = data['AAPL'].Close
        spy_close_yesterday = self.closes['SPY'][-2]

        spy_sma_today = sum(self.closes['SPY'][-20:]) / 20
        spy_sma_yesterday = sum(self.closes['SPY'][-21:-1]) / 20

        aapl_rsi = self._calculate_rsi(self.closes['AAPL'][-14:])

        if self.strategy_a_lot > 0:
            if spy_close_yesterday >= spy_sma_yesterday and spy_close < spy_sma_today:
                self.Liquidate('SPY')
                self.strategy_a_lot = 0

        if self.strategy_b_lot > 0:
            if aapl_rsi > 60:
                self.Liquidate('AAPL')
                self.strategy_b_lot = 0

        if self.strategy_a_lot == 0:
            if spy_close_yesterday <= spy_sma_yesterday and spy_close > spy_sma_today:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                amount = portfolio_value * 0.4
                shares = int(amount / spy_close)
                if shares > 0:
                    self.MarketOrder('SPY', shares)
                    self.strategy_a_lot = shares

        if self.strategy_b_lot == 0:
            if self._is_red_for_n_days(self.closes['AAPL'], 3):
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / aapl_close)
                    self.MarketOrder('AAPL', shares)
                    self.strategy_b_lot = shares

    def _is_red_for_n_days(self, history, n):
        if len(history) < n + 1:
            return False

        for i in range(-n, 0):
            if history[i] >= history[i - 1]:
                return False
        return True

    def _calculate_rsi(self, prices):
        if len(prices) < 2:
            return 50

        gains = 0.0
        losses = 0.0

        for i in range(1, len(prices)):
            change = prices[i] - prices[i - 1]
            if change > 0:
                gains += change
            else:
                losses += -change

        avg_gain = gains / len(prices)
        avg_loss = losses / len(prices)

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 0

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

