class TwoStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        for symbol in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.AddEquity(symbol, Resolution.Daily)

        self.sma_spy = self.SMA("SPY", 20, Resolution.Daily)
        self.rsi_aapl = self.RSI("AAPL", 14, Resolution.Daily)

        self.spy_close = RollingWindow[float](2)
        self.spy_sma = RollingWindow[float](2)
        self.aapl_close = RollingWindow[float](2)

        self.red_days_aapl = 0

    def OnData(self, data):
        for symbol in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            if symbol not in data:
                return

        self.spy_close.Add(data["SPY"].Close)
        if self.sma_spy.IsReady:
            self.spy_sma.Add(self.sma_spy.Current.Value)
        self.aapl_close.Add(data["AAPL"].Close)

        if not self.sma_spy.IsReady or not self.rsi_aapl.IsReady:
            return

        if self.spy_sma.Count < 2 or self.aapl_close.Count < 2:
            return

        if self.aapl_close[0] < self.aapl_close[1]:
            self.red_days_aapl += 1
        else:
            self.red_days_aapl = 0

        self.EvaluateStrategyA()
        self.EvaluateStrategyB()

    def EvaluateStrategyA(self):
        spy_position = self.Portfolio["SPY"].Quantity

        if spy_position > 0:
            if self.spy_close[1] >= self.spy_sma[1] and self.spy_close[0] < self.spy_sma[0]:
                self.Liquidate("SPY")
        elif spy_position == 0:
            if self.spy_close[1] <= self.spy_sma[1] and self.spy_close[0] > self.spy_sma[0]:
                total_value = self.Portfolio.TotalPortfolioValue
                invest_amount = total_value * 0.40
                shares = int(invest_amount / self.spy_close[0])
                if shares > 0:
                    self.Buy("SPY", shares)

    def EvaluateStrategyB(self):
        aapl_position = self.Portfolio["AAPL"].Quantity

        if aapl_position > 0:
            if self.rsi_aapl.Current.Value > 60:
                self.Liquidate("AAPL")
        elif aapl_position == 0:
            if self.red_days_aapl >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / self.aapl_close[0])
                    if shares > 0:
                        self.Buy("AAPL", shares)

