        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.spy_closes = []
        self.aapl_closes = []

        self.spy_prev_above_sma = None
        self.aapl_prev_red_days = 0

        self.spy_sma_period = 20
        self.aapl_rsi_period = 14
        self.warmup_period = 20

    def OnData(self, data: Slice):
        for ticker in self.tickers:
            if self.symbols[ticker] not in data:
                return

        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        if len(self.spy_closes) < self.warmup_period:
            return
        if len(self.aapl_closes) < self.warmup_period:
            return

        sma = sum(self.spy_closes[-self.spy_sma_period:]) / self.spy_sma_period
        spy_above_sma = spy_close > sma

        aapl_red_days = 0
        if aapl_close < self.aapl_closes[-2]:
            aapl_red_days = self.aapl_prev_red_days + 1

        rsi = self._calculate_rsi(self.aapl_closes, self.aapl_rsi_period)

        self._check_sells(spy_above_sma, rsi)
        self._check_buys(spy_above_sma, aapl_red_days)

        self.spy_prev_above_sma = spy_above_sma
        self.aapl_prev_red_days = aapl_red_days

    def _check_sells(self, spy_above_sma, rsi):
        if self.strategy_a_lot > 0:
            if self.spy_prev_above_sma is True and not spy_above_sma:
                self.Sell(self.symbols["SPY"], self.strategy_a_lot)
                self.strategy_a_lot = 0

        if self.strategy_b_lot > 0:
            if rsi is not None and rsi > 60:
                self.Sell(self.symbols["AAPL"], self.strategy_b_lot)
                self.strategy_b_lot = 0

    def _check_buys(self, spy_above_sma, aapl_red_days):
        if self.strategy_a_lot == 0:
            if self.spy_prev_above_sma is False and spy_above_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                investment = portfolio_value * 0.40
                spy_price = self.spy_closes[-1]
                shares = int(investment / spy_price)
                if shares > 0:
                    self.Buy(self.symbols["SPY"], shares)
                    self.strategy_a_lot = shares

        if self.strategy_b_lot == 0:
            if aapl_red_days >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    aapl_price = self.aapl_closes[-1]
                    shares = int(20000 / aapl_price)
                    if shares > 0:
                        self.Buy(self.symbols["AAPL"], shares)
                        self.strategy_b_lot = shares

    def _calculate_rsi(self, closes, period):
        if len(closes) < period + 1:
            return None

        recent = closes[-period-1:]

        gains = 0.0
        losses = 0.0
        for i in range(1, len(recent)):
            change = recent[i] - recent[i-1]
            if change > 0:
                gains += change
            else:
                losses += -change

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

