        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in self.tickers:
            self.AddEquity(ticker, Resolution.Daily)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_b_consecutive_red_days = 0

        self.spy_closes = []
        self.aapl_closes = []

    def OnData(self, data):
        for ticker in self.tickers:
            if not data.ContainsKey(ticker):
                return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        if len(self.spy_closes) < 21:
            return

        spy_ma_today = sum(self.spy_closes[-20:]) / 20.0
        spy_ma_yesterday = sum(self.spy_closes[-21:-1]) / 20.0

        spy_close_today = self.spy_closes[-1]
        spy_close_yesterday = self.spy_closes[-2]

        aapl_rsi = self.CalculateRSI(self.aapl_closes, 14)

        aapl_close_today = self.aapl_closes[-1]
        aapl_close_yesterday = self.aapl_closes[-2]

        if aapl_close_today < aapl_close_yesterday:
            self.strategy_b_consecutive_red_days += 1
        else:
            self.strategy_b_consecutive_red_days = 0

        if self.strategy_a_lot > 0:
            if spy_close_yesterday >= spy_ma_yesterday and spy_close_today < spy_ma_today:
                self.Liquidate("SPY")
                self.strategy_a_lot = 0

        if self.strategy_b_lot > 0:
            if aapl_rsi > 60:
                self.Liquidate("AAPL")
                self.strategy_b_lot = 0

        if self.strategy_a_lot == 0:
            if spy_close_yesterday <= spy_ma_yesterday and spy_close_today > spy_ma_today:
                self.SetHoldings("SPY", 0.4)
                self.strategy_a_lot = self.Portfolio["SPY"].Quantity

        if self.strategy_b_lot == 0:
            if self.strategy_b_consecutive_red_days >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    self.Buy("AAPL", shares_to_buy)
                    self.strategy_b_lot = shares_to_buy

    def CalculateRSI(self, closes, period):
        if len(closes) < period + 1:
            return 0

        gains = 0.0
        losses = 0.0

        for i in range(-period, 0):
            change = closes[i] - closes[i-1]
            if change > 0:
                gains += change
            else:
                losses += abs(change)

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100.0

        rs = avg_gain / avg_loss
        rsi = 100.0 - (100.0 / (1.0 + rs))

        return rsi

