from AlgorithmImports import *

class QuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.closes = {symbol: [] for symbol in self.symbols}

        for symbol in self.symbols:
            self.AddEquity(symbol, Resolution.Daily)

        self.strategy_a_symbol = 'SPY'
        self.strategy_b_symbol = 'AAPL'
        self.strategy_b_rsi = RelativeStrengthIndex(14)

    def OnData(self, data):
        for symbol in self.symbols:
            if symbol not in data:
                return

        for symbol in self.symbols:
            self.closes[symbol].append(data[symbol].Close)

        if len(self.closes['AAPL']) >= 15:
            self.strategy_b_rsi.Update(data['AAPL'])

        if len(self.closes['SPY']) < 101 or len(self.closes['AAPL']) < 4:
            return
        if not self.strategy_b_rsi.IsReady:
            return

        spy_price = data['SPY'].Close
        aapl_price = data['AAPL'].Close

        strategy_a_quantity = self.Portfolio[self.strategy_a_symbol].Quantity
        if strategy_a_quantity > 0:
            if self._crosses_below(self.strategy_a_symbol):
                self.Liquidate(self.strategy_a_symbol)
        else:
            if self._crosses_above(self.strategy_a_symbol):
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.40
                shares_to_buy = int(invest_amount / spy_price)
                if shares_to_buy > 0:
                    self.Buy(self.strategy_a_symbol, shares_to_buy)

        strategy_b_quantity = self.Portfolio[self.strategy_b_symbol].Quantity
        if strategy_b_quantity > 0:
            if self.strategy_b_rsi.Current.Value > 60:
                self.Liquidate(self.strategy_b_symbol)
        else:
            if self._is_red_for_n_days(self.strategy_b_symbol, 3):
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_price)
                    if shares_to_buy > 0:
                        self.Buy(self.strategy_b_symbol, shares_to_buy)

    def _crosses_above(self, symbol):
        closes = self.closes[symbol]
        if len(closes) < 101:
            return False

        today_close = closes[-1]
        yesterday_close = closes[-2]
        today_sma = sum(closes[-100:]) / 100
        yesterday_sma = sum(closes[-101:-1]) / 100

        return yesterday_close <= yesterday_sma and today_close > today_sma

    def _crosses_below(self, symbol):
        closes = self.closes[symbol]
        if len(closes) < 101:
            return False

        today_close = closes[-1]
        yesterday_close = closes[-2]
        today_sma = sum(closes[-100:]) / 100
        yesterday_sma = sum(closes[-101:-1]) / 100

        return yesterday_close >= yesterday_sma and today_close < today_sma

    def _is_red_for_n_days(self, symbol, n):
        closes = self.closes[symbol]
        if len(closes) < n + 1:
            return False

        for i in range(1, n + 1):
            if closes[-i] >= closes[-(i + 1)]:
                return False

        return True

