            if rsi > 60:
                self.MarketOrder(self.symbols['AAPL'], -aapl_qty)
                aapl_qty = 0

        # Strategy A buy
        if spy_qty == 0 and spy_len >= 101:
            spy_closes = self.history_data['SPY']
            ma_today = sum(spy_closes[-100:]) / 100.0
            ma_yesterday = sum(spy_closes[-101:-1]) / 100.0

            if spy_closes[-2] <= ma_yesterday and spy_closes[-1] > ma_today:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.4
                shares = int(target_value / spy_close)
                if shares > 0:
                    self.MarketOrder(self.symbols['SPY'], shares)

        # Strategy B buy
        if aapl_qty == 0 and aapl_len >= 4:
            aapl_closes = self.history_data['AAPL']

            is_red_3_days = (aapl_closes[-1] < aapl_closes[-2] and
                             aapl_closes[-2] < aapl_closes[-3] and
