            if is_red_3_days:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.symbols['AAPL'], shares)

    def _calculate_rsi(self, prices):
        if len(prices) < 14:
            return 50

        prices = prices[-14:]

        gains_sum = 0
        losses_sum = 0
        for i in range(1, len(prices)):
            change = prices[i] - prices[i-1]
            if change > 0:
                gains_sum += change
            else:
                losses_sum += abs(change)

        avg_gain = gains_sum / 14.0
        avg_loss = losses_sum / 14.0

        if avg_loss == 0:
            return 100

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

