            if self.strategy_b_shares == 0:
                if self.aapl_red_streak >= 3:
                    cash = self.Portfolio.Cash
                    if cash >= 20000:
                        shares = int(20000 / aapl_close)
                        if shares > 0:
                            self.Buy(self.symbols["AAPL"], shares)
                            self.strategy_b_shares = shares

    def ComputeRSI(self, prices):
        if len(prices) < 2:
            return 50

        gains = 0
        losses = 0

        for i in range(1, len(prices)):
            change = prices[i] - prices[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / len(prices)
        avg_loss = losses / len(prices)

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

