class Strategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for symbol in self.symbols:
            self.AddEquity(symbol, Resolution.Daily)

        self.price_history = {symbol: [] for symbol in self.symbols}

        self.prev_spy_close = None
        self.prev_spy_ma100 = None

        self.aapl_red_streak = 0
        self.prev_aapl_close = None

    def OnData(self, data):
        if not all(data.ContainsKey(symbol) for symbol in self.symbols):
            return

        current_prices = {symbol: data[symbol].Close for symbol in self.symbols}

        for symbol in self.symbols:
            self.price_history[symbol].append(current_prices[symbol])

        if len(self.price_history["SPY"]) < 100 or len(self.price_history["AAPL"]) < 15:
            return

        spy_close = current_prices["SPY"]
        aapl_close = current_prices["AAPL"]

        spy_ma100 = sum(self.price_history["SPY"][-100:]) / 100
        aapl_rsi = self._calculate_rsi(self.price_history["AAPL"])

        spy_shares = self.Portfolio["SPY"].Quantity
        aapl_shares = self.Portfolio["AAPL"].Quantity

        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        self.prev_aapl_close = aapl_close

        # Sells
        if spy_shares > 0:
            if (self.prev_spy_close is not None and self.prev_spy_ma100 is not None and
                self.prev_spy_close >= self.prev_spy_ma100 and spy_close < spy_ma100):
                self.MarketOrder("SPY", -spy_shares)
                spy_shares = 0

        if aapl_shares > 0:
            if aapl_rsi > 60:
                self.MarketOrder("AAPL", -aapl_shares)
                aapl_shares = 0

        # Buys
        if spy_shares == 0:
            if (self.prev_spy_close is not None and self.prev_spy_ma100 is not None and
                self.prev_spy_close <= self.prev_spy_ma100 and spy_close > spy_ma100):
                portfolio_value = self.Portfolio.TotalPortfolioValue
                investment = portfolio_value * 0.4
                shares = int(investment / spy_close)
                if shares > 0:
                    self.MarketOrder("SPY", shares)
                    spy_shares = shares

        if aapl_shares == 0:
            if self.aapl_red_streak >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder("AAPL", shares)
                        aapl_shares = shares

        self.prev_spy_close = spy_close
        self.prev_spy_ma100 = spy_ma100

    def _calculate_rsi(self, prices):
        if len(prices) < 15:
            return None

        recent = prices[-15:]
        gains = 0
        losses = 0

